s = open('build.js', encoding='utf8').read()

# ---------- shared blocks ----------
blocks = r'''
const split = (sub, h, paras, img, list, flip, cta) => `<section class="section-padding"><div class="container"><div class="row g-5 align-items-center ${flip ? 'flex-row-reverse' : ''}"><div class="col-lg-6 wow fadeInUp"><div class="rv-split-img"><img src="${img}" alt="${h}" loading="lazy"></div></div><div class="col-lg-6"><div class="section-title"><span class="sub-title">${sub}</span><h2 class="char-animation">${h}</h2></div>${paras.map(p => `<p class="mb-3">${p}</p>`).join('')}${list ? `<ul class="rv-checks">${list.map(x => `<li><i class="fa-solid fa-circle-check"></i>${x}</li>`).join('')}</ul>` : ''}${cta ? `<a href="${cta[0]}" class="theme-btn mt-3">${cta[1]} <i class="fa-solid fa-arrow-right"></i></a>` : ''}</div></div></div></section>`;
const compareTable = () => `<section class="section-padding section-bg"><div class="container">${title('Compare Materials', 'Choose the Right Material at a Glance')}<div class="rv-table-wrap"><table class="rv-compare"><thead><tr><th>Material</th><th>Type</th><th>Best for</th><th>Key finish / weave</th><th>MOQ</th></tr></thead><tbody>${P.map(p => `<tr><td data-l="Material"><a href="${p.s}.html"><b>${p.n}</b></a></td><td data-l="Type">${p.k}</td><td data-l="Best for">${p.ap.slice(0, 3).join(', ')}</td><td data-l="Key finish / weave">${(p.spec[3] || p.spec[1])[1]}</td><td data-l="MOQ">${p.spec[p.spec.length - 1][1]}</td></tr>`).join('')}</tbody></table></div></div></section>`;
const shadeBoard = () => `<section class="section-padding"><div class="container">${title('Shade Library', 'A Palette Drawn From Indian Craft')}<p class="text-center mx-auto mb-5" style="max-width:780px">Every material is available in its signature shades below, and we match any Pantone, swatch or photograph through our dye house. Tap a shade to request it.</p><div class="row g-4">${P.map(p => `<div class="col-lg-6"><div class="rv-shadecard"><h3><a href="${p.s}.html">${p.n}</a></h3><div class="swatches">${p.sh.map(x => `<a class="swatch" href="contact.html?subject=Shade&product=${enc(p.n + ' – ' + x[0])}"><span style="background:${x[1]}"></span>${x[0]}</a>`).join('')}</div></div></div>`).join('')}</div></div></section>`;
const APPS = [['fa-ring', 'Bridal & Occasion Wear', 'Banarasi brocade, zari and silk for lehengas, sarees and sherwanis.'], ['fa-shirt', 'Everyday Apparel', 'Mulmul, linen and block-print cottons for kurtas, shirts and dresses.'], ['fa-couch', 'Home & Interiors', 'Cushions, curtains, bedding and upholstery in handloom and brocade.'], ['fa-user-tie', 'Menswear & Tailoring', 'Fine cotton shirting, merino and linen for bespoke and ready-to-wear.'], ['fa-baby', 'Kidswear', 'Soft, breathable, skin-friendly cottons and natural-dye options.'], ['fa-globe', 'Export & Private Label', 'Consistent lots with full test reports and custom labelling.']];
const CERTS = [['fa-leaf', 'GOTS Organic Cotton', 'Organic yarn and fabric lines available with transaction certificates.'], ['fa-vial', 'Azo-Free Dyes', 'Every dye lot tested for restricted substances before dispatch.'], ['fa-award', 'Silk Mark & GI Heritage', 'Authentic silk and region-specific weaves documented at source.'], ['fa-clipboard-check', 'In-House Quality Lab', 'Colour-fastness, shrinkage, GSM, tensile and count tests on every lot.'], ['fa-recycle', 'Water Recycling', 'Effluent treatment and recycled water in our dye house.'], ['fa-people-group', 'Fair Trade Practices', 'Transparent, pre-agreed rates with artisan clusters.']];
'''
s = s.replace("const write = (f, html)", blocks + "\nconst write = (f, html)", 1)

# ---------- collections page ----------
coll_extra = """${split('Fibre to Fabric', 'How Every Material Is Made', ['Each material follows a documented route: fibre selection at source, spinning or reeling, dyeing in our Surat dye house, weaving by partner clusters, hand finishing and a three-gate quality inspection.', 'You can request the full production passport for any lot, showing where it was grown, who spun or wove it and which tests it passed.'], u('machineSpools', 1300, 1000), ['Fibre graded for staple length, denier and purity', 'Spun, twisted and dyed under controlled conditions', 'Woven on handlooms and modern looms by trained artisans', 'Finished, inspected and packed to export standards'], false, ['about.html', 'Read Our Story'])}
${compareTable()}
${featureGrid('Shop by Application', 'What Will You Create?', APPS)}
${shadeBoard()}
${split('Custom Development', 'Your Brief, Our Looms', ['Need an exclusive count, a bespoke motif, a custom jacquard or a proprietary shade? Our design desk develops yarns and fabrics to your brief, from first sketch through lab dip, sample metre and pilot lot to bulk production.', 'Minimum quantities for custom development start low so that boutiques and new labels can create something truly their own.'], u('atelier', 1300, 1000), ['Custom counts, twists and blends', 'Exclusive motifs, borders and jacquards', 'Pantone-matched natural and azo-free dyeing', 'Private labelling and bespoke packing'], true, ['contact.html?subject=Custom%20Order', 'Start a Custom Project'])}
${featureGrid('Standards & Certifications', 'Quality You Can Document', CERTS, 'section-bg')}
"""
s = s.replace("${featureGrid('Why Rajvastra', 'What Every Material Comes With', PROMISE.slice(0, 3), 'section-bg')}\n${steps('How to Order'", coll_extra + "${steps('How to Order'", 1)

# ---------- about page ----------
about_extra = """${split('A Note From Our Founder', 'Cloth Is Memory. We Simply Help It Travel.', ['“When my grandfather started trading yarn in Surat in 1987, he used to say that every thread carries the hands that made it. Four decades on, that is still how we work: we know the farms, the reelers, the dyers and the weaver families behind every metre we sell.', 'Our job is to protect that chain of craft and make it easy for designers anywhere in the world to use it. If we do that well, the cloth will speak for itself.”'], u('weaverMan', 1300, 1000), ['Direct relationships with 14 craft clusters', 'No middlemen between weaver and customer', 'A promise of honest provenance on every order'], false, ['contact.html', 'Meet the Team'])}
<section class="section-padding section-bg"><div class="container">${title('The Atelier Teams', 'The People Behind Every Order')}<div class="row g-4">${[['Design Desk', 'Trend forecasting, custom motif and colour development, and mood-board sourcing.', 'atelier2'], ['Dye House', 'Natural and azo-free dyeing, lab dips and shade matching in Surat.', 'hanks2'], ['Quality Lab', 'Count, strength, shrinkage and colour-fastness testing on every lot.', 'spoolsVert'], ['Export Desk', 'Documentation, private label, packing and worldwide logistics.', 'portDusk']].map((t, i) => `<div class="col-xl-3 col-md-6 wow fadeInUp" data-wow-delay="${i * 0.15}s"><div class="rv-card"><div class="rv-img" style="aspect-ratio:4/3"><img src="${u(t[2], 800, 600)}" alt="${t[0]}" loading="lazy"></div><div class="rv-body"><h3>${t[0]}</h3><p>${t[1]}</p></div></div></div>`).join('')}</div></div></section>
${steps('Our Craft Process', 'Six Stages of Quality, In Depth', [['Fibre sourcing', 'Cotton, silk, wool and zari are selected at origin and graded for length, purity and strength.'], ['Spinning & reeling', 'Fibre is spun or reeled to exact counts and twists on modern machines and traditional charkhas.'], ['Dyeing', 'Natural and azo-free dye lots are developed, lab-dipped and colour-matched in our Surat dye house.'], ['Weaving', 'Handloom and power-loom partners weave to our specifications, with design review at every stage.'], ['Finishing', 'Soft-washing, calendering and hand finishing give each fabric its signature handle.'], ['Inspection & packing', 'A three-gate quality check precedes export-grade packing and dispatch.']], '')}
${split('Who We Serve', 'Trusted by Designers, Mills and Fashion Houses', ['Our clients range from independent boutique designers to established fashion houses, textile mills, interior studios and export buyers in 30+ countries.', 'Whatever your scale, you get the same swatch standards, the same advisors and the same attention to detail.'], u('streetShops', 1300, 1000), ['Independent designers and bridal ateliers', 'Fashion houses and ready-to-wear brands', 'Interior designers and home-textile labels', 'Mills, traders and export importers'], true, ['wholesale.html', 'Explore Trade Programmes'])}
${featureGrid('Certifications & Standards', 'Quality You Can Document', CERTS, 'section-bg')}
"""
marker = "${featureGrid('Sustainability', 'Good for People and the Planet', PROMISE)}"
s = s.replace(marker, marker + "\n" + about_extra, 1)
open('build.js', 'w', encoding='utf8').write(s)
print('ok')
